// VoiceReader — license verification.
// Primary: Gumroad license API (the buyer's key is checked by Gumroad, no secret here).
// Fallback (offline / API unreachable): FNV-1a checksum key, generated by tools/make_license.py.
// NOTE: the offline check is obfuscation, not real security — determined users can bypass it.
// Gumroad remains the source of truth for real sales.
(function () {
  'use strict';
  const ALPH = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';

  function fnv1a(str) {
    let h = 0x811c9dc5 >>> 0;
    const bytes = new TextEncoder().encode(str);
    for (let i = 0; i < bytes.length; i++) {
      h ^= bytes[i];
      h = Math.imul(h, 0x01000193) >>> 0;
    }
    return h >>> 0;
  }

  function offlineChecksum(body, secret) {
    const h = fnv1a(secret + ':' + body);
    let out = '';
    for (let i = 0; i < 4; i++) out += ALPH[(h >>> (5 * i)) & 31];
    return out;
  }

  function normalize(raw) {
    return String(raw || '').trim().toUpperCase().replace(/\s+/g, '');
  }

  function offlineValidate(key) {
    const parts = key.split('-');
    if (parts.length !== 5 || parts[0] !== 'VR') return false;
    const groups = parts.slice(1);
    if (!groups.every(g => /^[A-Z2-7]{4}$/.test(g))) return false;
    const body = groups.slice(0, 3).join('');
    return offlineChecksum(body, window.VR_CONFIG.OFFLINE_SECRET) === groups[3];
  }

  async function gumroadVerify(key) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 8000);
    try {
      const body = new URLSearchParams({
        product_permalink: window.VR_CONFIG.GUMROAD_PERMALINK,
        license_key: key,
        increment_uses_count: 'false'
      });
      const res = await fetch('https://api.gumroad.com/v2/licenses/verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: body,
        signal: controller.signal
      });
      const json = await res.json().catch(() => null);
      if (!json) return null;               // unexpected response → fall back
      return json.success === true;
    } catch (err) {
      return null;                          // offline / CORS / timeout → fall back
    } finally {
      clearTimeout(timer);
    }
  }

  // Returns { ok: boolean, source: 'gumroad'|'offline'|null, reason?: string }
  async function verifyLicense(raw) {
    const key = normalize(raw);
    if (!/^VR(-[A-Z2-7]{4}){4}$/.test(key)) {
      return { ok: false, source: null, reason: 'Format: VR-XXXX-XXXX-XXXX-XXXX' };
    }
    const gumroad = await gumroadVerify(key);
    if (gumroad === true) return { ok: true, source: 'gumroad' };
    if (gumroad === false) return { ok: false, source: 'gumroad', reason: 'This key was rejected by Gumroad.' };
    // Gumroad unreachable → offline fallback
    const ok = offlineValidate(key);
    return { ok, source: 'offline', reason: ok ? undefined : 'Invalid key (offline check).' };
  }

  function isPro() {
    return localStorage.getItem('vr_pro') === '1';
  }
  function setPro(key) {
    localStorage.setItem('vr_pro', '1');
    localStorage.setItem('vr_license', normalize(key));
  }
  function clearPro() {
    localStorage.removeItem('vr_pro');
    localStorage.removeItem('vr_license');
  }

  window.VRLicense = { verifyLicense, isPro, setPro, clearPro, offlineValidate, normalize };
})();
